def transform(grid):
    out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v not in (1,)]
    # The frame color is the non-background color; its bounding box defines the outline.
    frame=max(set(v for row in grid for v in row), key=lambda v: sum(x==v for row in grid for x in row))
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==frame]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    for c in range(c0,c1+1):
        for r in (r0,r1):
            if out[r][c] != frame: out[r][c]=2
    for r in range(r0+1,r1):
        for c in (c0,c1):
            if out[r][c] != frame: out[r][c]=2
    return out
